import React, {
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";

import { useNavigate } from "react-router-dom";

import { useAuth } from "../context/AuthContext.js";
import request from "../services/api.js";

import "./Dashboard.css";

function Dashboard() {
  const {
    user,
    token,
    logout,
  } = useAuth();

  const navigate = useNavigate();

  const [activeSection, setActiveSection] =
    useState("Home");

  const [products, setProducts] = useState([]);
  const [orders, setOrders] = useState([]);

  const [loadingProducts, setLoadingProducts] =
    useState(false);

  const [loadingOrders, setLoadingOrders] =
    useState(false);

  const [error, setError] = useState("");

  const [profileMenuOpen, setProfileMenuOpen] =
    useState(false);

  const profileMenuRef = useRef(null);

  const storeName =
    typeof user?.tenant === "object"
      ? user.tenant.storeName ||
        user.tenant.name ||
        "My Store"
      : "My Store";

  const pendingOrders = useMemo(
    () =>
      orders.filter(
        (order) => order.status === "pending"
      ).length,
    [orders]
  );

  const totalSales = useMemo(
    () =>
      orders.reduce(
        (sum, order) =>
          sum + Number(order.totalAmount || 0),
        0
      ),
    [orders]
  );

  useEffect(() => {
    if (!token) {
      return;
    }

    const loadDashboardData = async () => {
      setLoadingProducts(true);
      setLoadingOrders(true);
      setError("");

      try {
        const [productsData, ordersData] =
          await Promise.all([
            request("/products", {
              method: "GET",
              token,
            }),
            request("/orders", {
              method: "GET",
              token,
            }),
          ]);

        setProducts(productsData.products || []);
        setOrders(ordersData.orders || []);
      } catch (requestError) {
        setError(
          requestError.message ||
            "Unable to load dashboard data"
        );
      } finally {
        setLoadingProducts(false);
        setLoadingOrders(false);
      }
    };

    loadDashboardData();
  }, [token]);

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (
        profileMenuRef.current &&
        !profileMenuRef.current.contains(
          event.target
        )
      ) {
        setProfileMenuOpen(false);
      }
    };

    document.addEventListener(
      "mousedown",
      handleClickOutside
    );

    return () => {
      document.removeEventListener(
        "mousedown",
        handleClickOutside
      );
    };
  }, []);

  const handleLogout = () => {
    logout();

    navigate("/", {
      replace: true,
    });
  };

  const handleSectionChange = (section) => {
    setActiveSection(section);
  };

  const openProfileSection = (section) => {
    setProfileMenuOpen(false);
    handleSectionChange(section);
  };

  const handleProfileLogout = () => {
    setProfileMenuOpen(false);
    handleLogout();
  };

  return (
    <div className="admin-layout">
      <header className="admin-topbar">
        <div className="admin-topbar-left">
          <div className="admin-logo">
            Tenant<span>Cart</span>
          </div>

          <button
            type="button"
            className="admin-home-button"
            onClick={() =>
              handleSectionChange("Home")
            }
          >
            <span className="admin-icon">←</span>
            <span>Home</span>
          </button>

          <button
            type="button"
            className="admin-search-button"
            onClick={() =>
              handleSectionChange("Search")
            }
          >
            <span className="admin-icon">⌕</span>
            <span>Search</span>
            <kbd>CTRL K</kbd>
          </button>
        </div>

        <div className="admin-topbar-right">
          <button
            type="button"
            className="admin-top-action"
            title="Preview store"
            onClick={() =>
              handleSectionChange("Online Store")
            }
          >
            ◉
          </button>

          <button
            type="button"
            className="admin-top-action"
            title="Notifications"
          >
            ♧
          </button>

          <div
            className="admin-profile-wrapper"
            ref={profileMenuRef}
          >
            <button
              type="button"
              className={`admin-profile ${
                profileMenuOpen
                  ? "admin-profile-open"
                  : ""
              }`}
              onClick={() =>
                setProfileMenuOpen(
                  (previousValue) => !previousValue
                )
              }
              aria-expanded={profileMenuOpen}
              aria-haspopup="menu"
            >
              <span className="admin-avatar">
                {user?.name
                  ?.charAt(0)
                  ?.toUpperCase() || "M"}
              </span>

              <span className="admin-profile-name">
                {user?.name || "Merchant"}
              </span>

              <span className="admin-profile-arrow">
                {profileMenuOpen ? "▴" : "▾"}
              </span>
            </button>

            {profileMenuOpen && (
              <div
                className="admin-profile-menu"
                role="menu"
              >
                <div className="admin-profile-menu-header">
                  <div className="admin-menu-avatar">
                    {user?.name
                      ?.charAt(0)
                      ?.toUpperCase() || "M"}
                  </div>

                  <div>
                    <strong>
                      {user?.name || "Merchant"}
                    </strong>

                    <span>
                      {user?.email ||
                        "No email available"}
                    </span>
                  </div>
                </div>

                <div className="admin-profile-menu-divider" />

                <button
                  type="button"
                  className="admin-profile-menu-item"
                  role="menuitem"
                  onClick={() =>
                    openProfileSection("Profile")
                  }
                >
                  <span>♙</span>
                  <span>Profile</span>
                </button>

                <button
                  type="button"
                  className="admin-profile-menu-item"
                  role="menuitem"
                  onClick={() =>
                    openProfileSection("Settings")
                  }
                >
                  <span>⚙</span>
                  <span>Store settings</span>
                </button>

                <button
                  type="button"
                  className="admin-profile-menu-item"
                  role="menuitem"
                  onClick={() =>
                    openProfileSection("Billing")
                  }
                >
                  <span>▣</span>
                  <span>Billing and plan</span>
                </button>

                <button
                  type="button"
                  className="admin-profile-menu-item"
                  role="menuitem"
                  onClick={() =>
                    openProfileSection("Help")
                  }
                >
                  <span>?</span>
                  <span>Help center</span>
                </button>

                <div className="admin-profile-menu-divider" />

                <button
                  type="button"
                  className="admin-profile-menu-item admin-profile-menu-logout"
                  role="menuitem"
                  onClick={handleProfileLogout}
                >
                  <span>↪</span>
                  <span>Log out</span>
                </button>
              </div>
            )}
          </div>
        </div>
      </header>

      <div className="admin-body">
        <aside className="admin-sidebar">
          <div>
            <div className="admin-store-switcher">
              <div className="admin-store-avatar">
                {storeName
                  .charAt(0)
                  .toUpperCase()}
              </div>

              <div className="admin-store-details">
                <strong>{storeName}</strong>
                <span>Merchant store</span>
              </div>

              <button
                type="button"
                className="admin-store-chevron"
                onClick={() =>
                  handleSectionChange("Settings")
                }
                aria-label="Open store settings"
              >
                ▾
              </button>
            </div>

            <nav className="admin-navigation">
              <SidebarItem
                icon="⌂"
                label="Home"
                active={activeSection === "Home"}
                onClick={() =>
                  handleSectionChange("Home")
                }
              />

              <SidebarItem
                icon="▣"
                label="Orders"
                count={pendingOrders}
                active={activeSection === "Orders"}
                onClick={() =>
                  handleSectionChange("Orders")
                }
              />

              <SidebarItem
                icon="◇"
                label="Products"
                active={activeSection === "Products"}
                onClick={() =>
                  handleSectionChange("Products")
                }
              />

              <div className="admin-sub-navigation">
                <SubNavigationItem
                  label="Collections"
                  active={
                    activeSection === "Collections"
                  }
                  onClick={() =>
                    handleSectionChange("Collections")
                  }
                />

                <SubNavigationItem
                  label="Inventory"
                  active={
                    activeSection === "Inventory"
                  }
                  onClick={() =>
                    handleSectionChange("Inventory")
                  }
                />

                <SubNavigationItem
                  label="Purchase orders"
                  active={
                    activeSection === "Purchase orders"
                  }
                  onClick={() =>
                    handleSectionChange("Purchase orders")
                  }
                />

                <SubNavigationItem
                  label="Transfers"
                  active={
                    activeSection === "Transfers"
                  }
                  onClick={() =>
                    handleSectionChange("Transfers")
                  }
                />
              </div>

              <div className="admin-navigation-section">
                <p className="admin-navigation-label">
                  Manage
                </p>

                <SidebarItem
                  icon="♟"
                  label="Customers"
                  active={activeSection === "Customers"}
                  onClick={() =>
                    handleSectionChange("Customers")
                  }
                />

                <SidebarItem
                  icon="◔"
                  label="Growth"
                  active={activeSection === "Growth"}
                  onClick={() =>
                    handleSectionChange("Growth")
                  }
                />

                <SidebarItem
                  icon="✥"
                  label="Discounts"
                  active={activeSection === "Discounts"}
                  onClick={() =>
                    handleSectionChange("Discounts")
                  }
                />

                <SidebarItem
                  icon="▤"
                  label="Content"
                  active={activeSection === "Content"}
                  onClick={() =>
                    handleSectionChange("Content")
                  }
                />

                <SidebarItem
                  icon="◑"
                  label="Markets"
                  active={activeSection === "Markets"}
                  onClick={() =>
                    handleSectionChange("Markets")
                  }
                />

                <SidebarItem
                  icon="▥"
                  label="Analytics"
                  active={activeSection === "Analytics"}
                  onClick={() =>
                    handleSectionChange("Analytics")
                  }
                />
              </div>

              <div className="admin-navigation-section">
                <p className="admin-navigation-label">
                  Sales channels
                </p>

                <SidebarItem
                  icon="▣"
                  label="Online Store"
                  active={
                    activeSection === "Online Store"
                  }
                  onClick={() =>
                    handleSectionChange("Online Store")
                  }
                />
              </div>

              <div className="admin-navigation-section">
                <p className="admin-navigation-label">
                  System
                </p>

                <SidebarItem
                  icon="⚙"
                  label="Settings"
                  active={activeSection === "Settings"}
                  onClick={() =>
                    handleSectionChange("Settings")
                  }
                />
              </div>
            </nav>
          </div>
        </aside>

        <main className="admin-main">
          <div className="admin-content-header">
            <div>
              <div className="admin-breadcrumb">
                Store
                <span>/</span>
                {activeSection}
              </div>

              <h1>{activeSection}</h1>
              <p>{storeName}</p>
            </div>

            <div className="admin-header-actions">
              <button
                type="button"
                className="admin-light-button"
                onClick={() =>
                  handleSectionChange("Online Store")
                }
              >
                ◉ View store
              </button>

              <button
                type="button"
                className="admin-primary-button"
                onClick={() =>
                  handleSectionChange("Products")
                }
              >
                View products
              </button>
            </div>
          </div>

          {error && (
            <div className="admin-error">
              {error}
            </div>
          )}

          {activeSection === "Home" && (
            <HomeContent
              user={user}
              products={products}
              orders={orders}
              pendingOrders={pendingOrders}
              totalSales={totalSales}
              loadingProducts={loadingProducts}
              loadingOrders={loadingOrders}
              onNavigate={handleSectionChange}
            />
          )}

          {activeSection === "Products" && (
            <ProductsContent
              products={products}
              loading={loadingProducts}
              onAddProduct={() =>
                handleSectionChange("Add product")
              }
            />
          )}

          {activeSection === "Orders" && (
            <OrdersContent
              orders={orders}
              loading={loadingOrders}
            />
          )}

          {![
            "Home",
            "Products",
            "Orders",
          ].includes(activeSection) && (
            <ComingSoonContent
              section={activeSection}
            />
          )}
        </main>
      </div>
    </div>
  );
}

function SidebarItem({
  icon,
  label,
  count,
  active,
  onClick,
}) {
  return (
    <button
      type="button"
      className={`admin-sidebar-item ${
        active
          ? "admin-sidebar-item-active"
          : ""
      }`}
      onClick={onClick}
    >
      <span className="admin-sidebar-icon">
        {icon}
      </span>

      <span className="admin-sidebar-label">
        {label}
      </span>

      {count > 0 && (
        <span className="admin-sidebar-count">
          {count}
        </span>
      )}
    </button>
  );
}

function SubNavigationItem({
  label,
  active,
  onClick,
}) {
  return (
    <button
      type="button"
      className={
        active
          ? "admin-sub-item-active"
          : ""
      }
      onClick={onClick}
    >
      {label}
    </button>
  );
}

function HomeContent({
  user,
  products,
  orders,
  pendingOrders,
  totalSales,
  loadingProducts,
  loadingOrders,
  onNavigate,
}) {
  return (
    <>
      <section className="admin-welcome-card">
        <div>
          <span className="admin-eyebrow">
            Store overview
          </span>

          <h2>
            Good to see you, {user?.name
              ?.split(" ")?.[0] || "merchant"}.
          </h2>

          <p>
            Here is what is happening across your store
            today.
          </p>
        </div>

        <div className="admin-welcome-mark">
          TC
        </div>
      </section>

      <section className="admin-metric-grid">
        <MetricCard
          label="Total products"
          value={
            loadingProducts
              ? "—"
              : products.length
          }
          description="Products in your catalogue"
        />

        <MetricCard
          label="Orders"
          value={
            loadingOrders ? "—" : orders.length
          }
          description="Total customer orders"
        />

        <MetricCard
          label="Pending"
          value={
            loadingOrders
              ? "—"
              : pendingOrders
          }
          description="Orders requiring attention"
        />

        <MetricCard
          label="Total sales"
          value={
            loadingOrders
              ? "—"
              : `₹${totalSales.toLocaleString(
                  "en-IN"
                )}`
          }
          description="Recorded order value"
        />
      </section>

      <section className="admin-workspace-card">
        <div className="admin-workspace-toolbar">
          <div className="admin-tabs">
            <button
              type="button"
              className="admin-tab admin-tab-active"
            >
              Overview
            </button>

            <button
              type="button"
              className="admin-tab"
              onClick={() =>
                onNavigate("Products")
              }
            >
              Products
            </button>

            <button
              type="button"
              className="admin-tab"
              onClick={() =>
                onNavigate("Orders")
              }
            >
              Orders
            </button>
          </div>

          <div className="admin-toolbar-actions">
            <button
              type="button"
              className="admin-tool-button"
              onClick={() =>
                onNavigate("Search")
              }
            >
              ⌕ Search
            </button>

            <button
              type="button"
              className="admin-tool-button"
            >
              ☷ Filter
            </button>

            <button
              type="button"
              className="admin-tool-button"
            >
              ↕
            </button>
          </div>
        </div>

        <div className="admin-overview-body">
          <div>
            <span className="admin-eyebrow">
              Your workspace
            </span>

            <h3>Build your catalogue</h3>

            <p>
              Add products that your customers will love,
              then manage inventory and orders from this
              workspace.
            </p>

            <div className="admin-action-row">
              <button
                type="button"
                className="admin-dark-button"
                onClick={() =>
                  onNavigate("Products")
                }
              >
                View products
              </button>

              <button
                type="button"
                className="admin-light-button"
                onClick={() =>
                  onNavigate("Orders")
                }
              >
                View orders
              </button>
            </div>
          </div>

          <div className="admin-product-illustration">
            <div className="admin-illustration-card">
              <span>◈</span>
              <small>PRODUCTS</small>
            </div>

            <div className="admin-illustration-card admin-illustration-card-tall">
              <span>◇</span>
              <small>STORE</small>
            </div>

            <div className="admin-illustration-card">
              <span>○</span>
              <small>ORDERS</small>
            </div>
          </div>
        </div>
      </section>
    </>
  );
}

function MetricCard({
  label,
  value,
  description,
}) {
  return (
    <article className="admin-metric-card">
      <span>{label}</span>
      <strong>{value}</strong>
      <small>{description}</small>
    </article>
  );
}

function ProductsContent({
  products,
  loading,
  onAddProduct,
}) {
  return (
    <section className="admin-workspace-card">
      <div className="admin-workspace-toolbar">
        <div className="admin-tabs">
          <button
            type="button"
            className="admin-tab admin-tab-active"
          >
            All
          </button>

          <button
            type="button"
            className="admin-tab"
            onClick={onAddProduct}
          >
            +
          </button>
        </div>

        <div className="admin-toolbar-actions">
          <button
            type="button"
            className="admin-tool-button"
          >
            ⌕ Search
          </button>

          <button
            type="button"
            className="admin-tool-button"
          >
            ☷ Filter
          </button>

          <button
            type="button"
            className="admin-tool-button"
          >
            ↕
          </button>
        </div>
      </div>

      {loading && (
        <div className="admin-empty-state">
          Loading products...
        </div>
      )}

      {!loading && products.length === 0 && (
        <div className="admin-empty-state">
          <div className="admin-empty-visual">
            ◈
          </div>

          <h2>Add your products</h2>

          <p>
            Start by stocking your store with products your
            customers will love.
          </p>

          <button
            type="button"
            className="admin-dark-button"
            onClick={onAddProduct}
          >
            + Add product
          </button>
        </div>
      )}

      {!loading && products.length > 0 && (
        <div className="admin-product-list">
          {products.map((product) => (
            <article
              key={product._id}
              className="admin-product-row"
            >
              <div className="admin-product-thumbnail">
                {product.imageUrl ? (
                  <img
                    src={product.imageUrl}
                    alt={product.name}
                  />
                ) : (
                  "◇"
                )}
              </div>

              <div className="admin-product-info">
                <strong>{product.name}</strong>
                <span>
                  {product.category || "General"}
                </span>
              </div>

              <span>
                ₹
                {Number(product.price).toLocaleString(
                  "en-IN"
                )}
              </span>

              <span>{product.stock} in stock</span>
            </article>
          ))}
        </div>
      )}
    </section>
  );
}

function OrdersContent({
  orders,
  loading,
}) {
  return (
    <section className="admin-workspace-card">
      <div className="admin-workspace-toolbar">
        <div className="admin-tabs">
          <button
            type="button"
            className="admin-tab admin-tab-active"
          >
            All orders
          </button>
        </div>

        <div className="admin-toolbar-actions">
          <button
            type="button"
            className="admin-tool-button"
          >
            ⌕ Search
          </button>

          <button
            type="button"
            className="admin-tool-button"
          >
            ☷ Filter
          </button>
        </div>
      </div>

      {loading && (
        <div className="admin-empty-state">
          Loading orders...
        </div>
      )}

      {!loading && orders.length === 0 && (
        <div className="admin-empty-state">
          <div className="admin-empty-visual">
            ▣
          </div>

          <h2>No orders yet</h2>

          <p>
            Customer orders will appear here after they
            purchase from your store.
          </p>
        </div>
      )}

      {!loading && orders.length > 0 && (
        <div className="admin-order-list">
          {orders.map((order) => (
            <article
              key={order._id}
              className="admin-order-row"
            >
              <div>
                <strong>
                  Order #{order._id.slice(-8)}
                </strong>

                <span>
                  {order.customer?.name || "Customer"}
                </span>
              </div>

              <span>
                ₹
                {Number(
                  order.totalAmount || 0
                ).toLocaleString("en-IN")}
              </span>

              <span
                className={`admin-status admin-status-${order.status}`}
              >
                {order.status}
              </span>
            </article>
          ))}
        </div>
      )}
    </section>
  );
}

function ComingSoonContent({
  section,
}) {
  return (
    <section className="admin-workspace-card">
      <div className="admin-empty-state">
        <div className="admin-empty-visual">
          ◌
        </div>

        <h2>{section}</h2>

        <p>
          This section is ready for the next TenantCart
          feature.
        </p>
      </div>
    </section>
  );
}

export default Dashboard;
